<?php declare(strict_types=1); namespace Annam; $title='Daily menu · '.$store->name(); ?>
<section class="wrap php-store-section"><header class="php-section-head"><div><p class="eyebrow">Freshly prepared</p><h1>Daily menu</h1><p><?= e((new \DateTimeImmutable($date))->format('l, j F Y')) ?></p></div><nav class="php-tabs"><?php foreach ([date('Y-m-d')=>'Today',date('Y-m-d',strtotime('+1 day'))=>'Tomorrow'] as $day=>$label): ?><a class="<?= $date===$day?'selected':'' ?>" href="?date=<?= e($day) ?>"><?= e($label) ?></a><?php endforeach; ?></nav></header><form class="php-date-bar" method="get"><label>Choose date <input type="date" name="date" value="<?= e($date) ?>" required min="<?= date('Y-m-d') ?>" max="<?= date('Y-m-d',strtotime('+1 day')) ?>"></label><button class="btn" type="submit">View menu</button></form>
<?php foreach ($menus as $meal): $slotId=(int)$meal['slot']['id']; ?><section class="php-store-section"><header class="php-section-head"><h2><?= e($meal['slot']['label']) ?></h2><p>Orders close <?= e(substr($meal['slot']['order_cutoff'],0,5)) ?></p></header><ul class="php-product-grid"><?php foreach ($meal['items'] as $product) require __DIR__.'/card.php'; ?></ul><?php if (!$meal['items']): ?><p>No dishes are available for this meal. Please check another date.</p><?php endif; ?></section><?php endforeach; ?></section>
